window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["ECC"]={"book":"ECC","editions":{"epo-londona":[[1,1,"Vortoj de la Predikanto, filo de David, reĝo en Jerusalem.","Vortoj de la Predikanto, filo de David, reĝo en Jerusalem."],[1,2,"Vantaĵo de vantaĵoj, diris la Predikanto; vantaĵo de vantaĵoj, ĉio estas vantaĵo.","Vantaĵo de vantaĵoj, diris la Predikanto; vantaĵo de vantaĵoj, ĉio estas vantaĵo."],[1,3,"Kian profiton havas la homo de ĉiuj siaj laboroj, kiujn li laboras sub la suno?","Kian profiton havas la homo de ĉiuj siaj laboroj, kiujn li laboras sub la suno?"],[1,4,"Generacio foriras kaj generacio venas, kaj la tero restas eterne.","Generacio foriras kaj generacio venas, kaj la tero restas eterne."],[1,5,"Leviĝas la suno kaj subiras la suno, kaj al sia loko ĝi rapidas, kaj tie ĝi leviĝas.","Leviĝas la suno kaj subiras la suno, kaj al sia loko ĝi rapidas, kaj tie ĝi leviĝas."],[1,6,"Iras al sudo kaj reiras al nordo, turniĝas, turniĝas en sia irado la vento, kaj al siaj rondoj revenas la vento.","Iras al sudo kaj reiras al nordo, turniĝas, turniĝas en sia irado la vento, kaj al siaj rondoj revenas la vento."],[1,7,"Ĉiuj riveroj iras al la maro, sed la maro ne pleniĝas; al la loko, al kiu la riveroj alfluas, ili alfluas ĉiam denove.","Ĉiuj riveroj iras al la maro, sed la maro ne pleniĝas; al la loko, al kiu la riveroj alfluas, ili alfluas ĉiam denove."],[1,8,"Ĉiuj aferoj estas lacigaj, ne povas homo tion eldiri; ne satiĝas la okulo de vidado, kaj ne pleniĝas la orelo de aŭdado.","Ĉiuj aferoj estas lacigaj, ne povas homo tion eldiri; ne satiĝas la okulo de vidado, kaj ne pleniĝas la orelo de aŭdado."],[1,9,"Kio estis, tio estos; kaj kio estis farata, tio estos farata; kaj ekzistas nenio nova sub la suno.","Kio estis, tio estos; kaj kio estis farata, tio estos farata; kaj ekzistas nenio nova sub la suno."],[1,10,"Ekzistas io, pri kio oni diras: Vidu, ĉi tio estas nova; sed ĝi estis jam en la eterna tempo, kiu estis antaŭ ni.","Ekzistas io, pri kio oni diras: Vidu, ĉi tio estas nova; sed ĝi estis jam en la eterna tempo, kiu estis antaŭ ni."],[1,11,"Ne restis memoro pri la antaŭuloj; kaj ankaŭ pri la posteuloj, kiuj estos, ne restos memoro ĉe tiuj, kiuj estos poste.","Ne restis memoro pri la antaŭuloj; kaj ankaŭ pri la posteuloj, kiuj estos, ne restos memoro ĉe tiuj, kiuj estos poste."],[1,12,"Mi, Predikanto, estis reĝo super Izrael en Jerusalem.","Mi, Predikanto, estis reĝo super Izrael en Jerusalem."],[1,13,"Kaj mi decidis en mia koro esplori kaj ekzameni per la saĝo ĉion, kio fariĝas sub la ĉielo: ĉi tiun malfacilan okupon Dio donis al la homidoj, por ke ili turmentiĝu per ĝi.","Kaj mi decidis en mia koro esplori kaj ekzameni per la saĝo ĉion, kio fariĝas sub la ĉielo: ĉi tiun malfacilan okupon Dio donis al la homidoj, por ke ili turmentiĝu per ĝi."],[1,14,"Mi vidis ĉiujn aferojn, kiuj fariĝas sub la suno; kaj jen, ĉio estas vantaĵo kaj entreprenoj ventaj.","Mi vidis ĉiujn aferojn, kiuj fariĝas sub la suno; kaj jen, ĉio estas vantaĵo kaj entreprenoj ventaj."],[1,15,"Kurbigitan oni ne povas rerektigi, kaj mankantan oni ne povas kalkuli.","Kurbigitan oni ne povas rerektigi, kaj mankantan oni ne povas kalkuli."],[1,16,"Mi meditis kun mia koro tiele: Jen mi kreskigis kaj multigis en mi sciencon pli ol ĉiuj, kiuj estis antaŭ mi en Jerusalem; kaj mia koro penetris multon da saĝo kaj scio.","Mi meditis kun mia koro tiele: Jen mi kreskigis kaj multigis en mi sciencon pli ol ĉiuj, kiuj estis antaŭ mi en Jerusalem; kaj mia koro penetris multon da saĝo kaj scio."],[1,17,"Sed kiam mi dediĉis mian koron, por ekkoni la saĝecon kaj ekkoni la malsaĝecon kaj sensencecon, mi eksciis, ke ankaŭ ĉi tio estas ventaĵo.","Sed kiam mi dediĉis mian koron, por ekkoni la saĝecon kaj ekkoni la malsaĝecon kaj sensencecon, mi eksciis, ke ankaŭ ĉi tio estas ventaĵo."],[1,18,"Ĉar ĉe multe da saĝeco estas multe da zorgemeco; kaj, kiu plimultigas siajn sciojn, tiu plimultigas siajn dolorojn.","Ĉar ĉe multe da saĝeco estas multe da zorgemeco; kaj, kiu plimultigas siajn sciojn, tiu plimultigas siajn dolorojn."],[2,1,"Mi diris en mia koro: Lasu, mi elprovos vin per ĝojo, kaj vi ĝuu bonon; sed jen ankaŭ ĉi tio estas vantaĵo.","Mi diris en mia koro: Lasu, mi elprovos vin per ĝojo, kaj vi ĝuu bonon; sed jen ankaŭ ĉi tio estas vantaĵo."],[2,2,"Pri la rido mi diris: Ĝi estas sensencaĵo! kaj pri la ĝojo: Kion ĝi havigas?","Pri la rido mi diris: Ĝi estas sensencaĵo! kaj pri la ĝojo: Kion ĝi havigas?"],[2,3,"Mi serĉis en mia koro, kiel plezurigi mian korpon per vino, kaj, dum mia koro min gvidas per saĝeco, sekvi ankaŭ malsaĝecon, ĝis mi ekvidos, kio estas bona por la homidoj, kion ili povus fari sub la ĉielo en la kalkulitaj tagoj de sia vivo.","Mi serĉis en mia koro, kiel plezurigi mian korpon per vino, kaj, dum mia koro min gvidas per saĝeco, sekvi ankaŭ malsaĝecon, ĝis mi ekvidos, kio estas bona por la homidoj, kion ili povus fari sub la ĉielo en la kalkulitaj tagoj de sia vivo."],[2,4,"Mi entreprenis grandajn farojn: mi konstruis al mi domojn, mi plantis al mi vinberejojn;","Mi entreprenis grandajn farojn: mi konstruis al mi domojn, mi plantis al mi vinberejojn;"],[2,5,"mi aranĝis al mi ĝardenojn kaj arbaretojn, kaj plantis en ili ĉiafruktajn arbojn;","mi aranĝis al mi ĝardenojn kaj arbaretojn, kaj plantis en ili ĉiafruktajn arbojn;"],[2,6,"mi aranĝis al mi akvujojn, por akvumi el ili arbaretojn, kiuj kreskigas arbojn;","mi aranĝis al mi akvujojn, por akvumi el ili arbaretojn, kiuj kreskigas arbojn;"],[2,7,"mi akiris al mi sklavojn kaj sklavinojn, kaj domanojn mi havis; ankaŭ da bruto granda kaj malgranda mi havis pli multe, ol ĉiuj, kiuj estis antaŭ mi en Jerusalem;","mi akiris al mi sklavojn kaj sklavinojn, kaj domanojn mi havis; ankaŭ da bruto granda kaj malgranda mi havis pli multe, ol ĉiuj, kiuj estis antaŭ mi en Jerusalem;"],[2,8,"mi kolektis al mi ankaŭ arĝenton kaj oron, kaj juvelojn de reĝoj kaj landoj; mi havigis al mi kantistojn kaj kantistinojn, kaj plezurojn de homidoj, kaj multajn amantinojn.","mi kolektis al mi ankaŭ arĝenton kaj oron, kaj juvelojn de reĝoj kaj landoj; mi havigis al mi kantistojn kaj kantistinojn, kaj plezurojn de homidoj, kaj multajn amantinojn."],[2,9,"Kaj mi pligrandigis kaj plimultigis ĉion pli ol ĉiuj, kiuj estis antaŭ mi en Jerusalem, kaj mia saĝeco restis kun mi.","Kaj mi pligrandigis kaj plimultigis ĉion pli ol ĉiuj, kiuj estis antaŭ mi en Jerusalem, kaj mia saĝeco restis kun mi."],[2,10,"Kaj ĉion, kion postulis miaj okuloj, mi ne rifuzis al ili; mi fortenis mian koron de nenia ĝojo, ĉar mia koro ĝojis pri ĉiuj miaj laboroj; kaj ĉi tio estis mia rekompenco por ĉiuj miaj laboroj.","Kaj ĉion, kion postulis miaj okuloj, mi ne rifuzis al ili; mi fortenis mian koron de nenia ĝojo, ĉar mia koro ĝojis pri ĉiuj miaj laboroj; kaj ĉi tio estis mia rekompenco por ĉiuj miaj laboroj."],[2,11,"Kaj mi ekrigardis ĉiujn farojn, kiujn faris miaj manoj, kaj ĉiujn laborojn, kiujn mi plenumis, por fari ilin: kaj jen, ĉio estas vantaĵo kaj ventaĵo, kaj nenia profito estas de ili sub la suno.","Kaj mi ekrigardis ĉiujn farojn, kiujn faris miaj manoj, kaj ĉiujn laborojn, kiujn mi plenumis, por fari ilin: kaj jen, ĉio estas vantaĵo kaj ventaĵo, kaj nenia profito estas de ili sub la suno."],[2,12,"Kaj mi turnis min, por rigardi saĝecon kaj malsaĝecon kaj sensencecon; ĉar kion povas fari homo, venonta post reĝo, en komparo kun tio, kion tiu jam antaŭ longe faris?","Kaj mi turnis min, por rigardi saĝecon kaj malsaĝecon kaj sensencecon; ĉar kion povas fari homo, venonta post reĝo, en komparo kun tio, kion tiu jam antaŭ longe faris?"],[2,13,"Kaj mi vidis, ke havas superecon la saĝeco antaŭ la malsaĝeco, kiel havas superecon lumo antaŭ mallumo.","Kaj mi vidis, ke havas superecon la saĝeco antaŭ la malsaĝeco, kiel havas superecon lumo antaŭ mallumo."],[2,14,"La saĝulo havas siajn okulojn en la kapo, kaj la malsaĝulo iras en mallumo; sed mi ankaŭ eksciis, ke unu sorto atingas ilin ĉiujn.","La saĝulo havas siajn okulojn en la kapo, kaj la malsaĝulo iras en mallumo; sed mi ankaŭ eksciis, ke unu sorto atingas ilin ĉiujn."],[2,15,"Kaj mi diris en mia koro: Ankaŭ min atingos tia sama sorto, kiel la malsaĝulon; por kio do mi estis pli saĝa? Kaj mi diris en mia koro, ke ankaŭ ĉi tio estas vantaĵo.","Kaj mi diris en mia koro: Ankaŭ min atingos tia sama sorto, kiel la malsaĝulon; por kio do mi estis pli saĝa? Kaj mi diris en mia koro, ke ankaŭ ĉi tio estas vantaĵo."],[2,16,"Ĉar pri la saĝulo ne restos memoro eterne tiel same, kiel pri la malsaĝulo; en la tempoj estontaj ĉio estos forgesita. Kaj ho ve, mortas saĝulo egale kiel malsaĝulo!","Ĉar pri la saĝulo ne restos memoro eterne tiel same, kiel pri la malsaĝulo; en la tempoj estontaj ĉio estos forgesita. Kaj ho ve, mortas saĝulo egale kiel malsaĝulo!"],[2,17,"Kaj mi ekmalamis la vivon; ĉar abomenindaj estas por mi la faroj, kiuj fariĝas sub la suno, ĉar ĉio estas vantaĵo kaj ventaĵo.","Kaj mi ekmalamis la vivon; ĉar abomenindaj estas por mi la faroj, kiuj fariĝas sub la suno, ĉar ĉio estas vantaĵo kaj ventaĵo."],[2,18,"Kaj mi ekmalamis ĉiun laboron, kiun mi laboris sub la suno; ĉar mi devos lasi ĝin al homo, kiu estos post mi.","Kaj mi ekmalamis ĉiun laboron, kiun mi laboris sub la suno; ĉar mi devos lasi ĝin al homo, kiu estos post mi."],[2,19,"Kaj kiu scias, ĉu estos saĝa aŭ malsaĝa tiu, kiu ekposedos mian tutan laboron, pri kiu mi penis kaj streĉis mian saĝon sub la suno? Ankaŭ ĉi tio estas vantaĵo.","Kaj kiu scias, ĉu estos saĝa aŭ malsaĝa tiu, kiu ekposedos mian tutan laboron, pri kiu mi penis kaj streĉis mian saĝon sub la suno? Ankaŭ ĉi tio estas vantaĵo."],[2,20,"Kaj mi decidis, ke mia koro atendu nenion de la tuta laboro, kiun mi laboris sub la suno.","Kaj mi decidis, ke mia koro atendu nenion de la tuta laboro, kiun mi laboris sub la suno."],[2,21,"Ĉar ofte oni vidas homon, kiu laboras en saĝo, scienco, kaj talento, kaj li devas fordoni sian akiron al homo, kiu ne laboris por ĝi; ĉi tio ankaŭ estas vantaĵo kaj granda malbono.","Ĉar ofte oni vidas homon, kiu laboras en saĝo, scienco, kaj talento, kaj li devas fordoni sian akiron al homo, kiu ne laboris por ĝi; ĉi tio ankaŭ estas vantaĵo kaj granda malbono."],[2,22,"Kaj kio restas al la homo de lia tuta laborado kaj de la zorgoj de lia koro, kion li laboras sub la suno?","Kaj kio restas al la homo de lia tuta laborado kaj de la zorgoj de lia koro, kion li laboras sub la suno?"],[2,23,"Ĉar ĉiuj liaj tagoj estas suferoj, kaj liaj okupoj estas maltrankvileco; eĉ en la nokto ne trankviliĝas lia koro; ankaŭ ĉi tio estas vantaĵo.","Ĉar ĉiuj liaj tagoj estas suferoj, kaj liaj okupoj estas maltrankvileco; eĉ en la nokto ne trankviliĝas lia koro; ankaŭ ĉi tio estas vantaĵo."],[2,24,"Ne ekzistas alia bono por la homo, krom manĝi kaj trinki kaj igi sian animon ĝui plezuron de lia laborado; ankaŭ pri ĉi tio mi vidis, ke ĝi estas de la mano de Dio.","Ne ekzistas alia bono por la homo, krom manĝi kaj trinki kaj igi sian animon ĝui plezuron de lia laborado; ankaŭ pri ĉi tio mi vidis, ke ĝi estas de la mano de Dio."],[2,25,"Ĉar kiu povas manĝi, kaj kiu povas ĝui, sen Li?","Ĉar kiu povas manĝi, kaj kiu povas ĝui, sen Li?"],[2,26,"Ĉar al homo, kiu agas bone antaŭ Li, Li donas saĝon kaj scion kaj ĝojon, kaj al la pekulo Li donas la zorgemecon amasigi kaj kolekti, por poste transdoni al tiu, kiu agas bone antaŭ Dio; kaj ĉi tio estas vantaĵo kaj ventaĵo.","Ĉar al homo, kiu agas bone antaŭ Li, Li donas saĝon kaj scion kaj ĝojon, kaj al la pekulo Li donas la zorgemecon amasigi kaj kolekti, por poste transdoni al tiu, kiu agas bone antaŭ Dio; kaj ĉi tio estas vantaĵo kaj ventaĵo."],[3,1,"Por ĉio estas sezono, kaj tempo difinita estas por ĉiu afero sub la suno;","Por ĉio estas sezono, kaj tempo difinita estas por ĉiu afero sub la suno;"],[3,2,"estas tempo por naskiĝi, kaj tempo por morti; estas tempo por planti, kaj tempo por elŝiri la plantitaĵon;","estas tempo por naskiĝi, kaj tempo por morti; estas tempo por planti, kaj tempo por elŝiri la plantitaĵon;"],[3,3,"estas tempo por mortigi, kaj tempo por kuraci; estas tempo por detrui, kaj tempo por konstrui;","estas tempo por mortigi, kaj tempo por kuraci; estas tempo por detrui, kaj tempo por konstrui;"],[3,4,"estas tempo por plori, kaj tempo por ridi; estas tempo por ĝemi, kaj tempo por danci;","estas tempo por plori, kaj tempo por ridi; estas tempo por ĝemi, kaj tempo por danci;"],[3,5,"estas tempo por disĵeti ŝtonojn, kaj tempo por kolekti ŝtonojn; estas tempo por ĉirkaŭbraki, kaj tempo por foriri de ĉirkaŭbrakado;","estas tempo por disĵeti ŝtonojn, kaj tempo por kolekti ŝtonojn; estas tempo por ĉirkaŭbraki, kaj tempo por foriri de ĉirkaŭbrakado;"],[3,6,"estas tempo por serĉi, kaj tempo por perdi; estas tempo por konservi, kaj tempo por forĵeti;","estas tempo por serĉi, kaj tempo por perdi; estas tempo por konservi, kaj tempo por forĵeti;"],[3,7,"estas tempo por disŝiri, kaj tempo por kunkudri; estas tempo por silenti, kaj tempo por paroli;","estas tempo por disŝiri, kaj tempo por kunkudri; estas tempo por silenti, kaj tempo por paroli;"],[3,8,"estas tempo por ami, kaj tempo por malami; estas tempo por milito, kaj tempo por paco.","estas tempo por ami, kaj tempo por malami; estas tempo por milito, kaj tempo por paco."],[3,9,"Kian profiton havas faranto de tio, kion li laboras?","Kian profiton havas faranto de tio, kion li laboras?"],[3,10,"Mi vidis la penemecon, kiun Dio donis al la homidoj, por ke ili turmentiĝu per ĝi.","Mi vidis la penemecon, kiun Dio donis al la homidoj, por ke ili turmentiĝu per ĝi."],[3,11,"Ĉion Li kreis bela ĝiatempe; kaj scion pri la mondo Li enmetis en ilian koron, sed tiel, ke homo ne povas kompreni la farojn, kiujn faris Dio de la komenco ĝis la fino.","Ĉion Li kreis bela ĝiatempe; kaj scion pri la mondo Li enmetis en ilian koron, sed tiel, ke homo ne povas kompreni la farojn, kiujn faris Dio de la komenco ĝis la fino."],[3,12,"Mi scias, ke ekzistas nenia bono por ili, krom ĝoji kaj fari bonon en sia vivo.","Mi scias, ke ekzistas nenia bono por ili, krom ĝoji kaj fari bonon en sia vivo."],[3,13,"Kaj se homo manĝas kaj trinkas kaj ĝuas bonon de sia tuta laborado, tio estas dono de Dio.","Kaj se homo manĝas kaj trinkas kaj ĝuas bonon de sia tuta laborado, tio estas dono de Dio."],[3,14,"Mi scias, ke ĉio, kion faras Dio, restas eterne; al ĝi oni nenion povas aldoni, kaj de ĝi oni nenion povas depreni; kaj Dio tion faris, ke oni Lin timu.","Mi scias, ke ĉio, kion faras Dio, restas eterne; al ĝi oni nenion povas aldoni, kaj de ĝi oni nenion povas depreni; kaj Dio tion faris, ke oni Lin timu."],[3,15,"Kio fariĝis, tio ekzistas de longe; kaj kio estas fariĝonta, tio antaŭ longe jam estis, kaj Dio revokas pasintaĵon.","Kio fariĝis, tio ekzistas de longe; kaj kio estas fariĝonta, tio antaŭ longe jam estis, kaj Dio revokas pasintaĵon."],[3,16,"Ankoraŭ mi vidis sub la suno: en la loko de juĝo, ke tie estas maljusteco; en la loko de vero, ke tie estas malico.","Ankoraŭ mi vidis sub la suno: en la loko de juĝo, ke tie estas maljusteco; en la loko de vero, ke tie estas malico."],[3,17,"Mi diris en mia koro: Piulon kaj malpiulon juĝos Dio; ĉar estas tempo por ĉiu afero, kaj por ĉio, kio fariĝas tie.","Mi diris en mia koro: Piulon kaj malpiulon juĝos Dio; ĉar estas tempo por ĉiu afero, kaj por ĉio, kio fariĝas tie."],[3,18,"Mi diris en mia koro: Ĉi tio estas pri la homidoj, ke Dio ilin elprovu, kaj ke ili vidu, ke ili estas bruto per si mem.","Mi diris en mia koro: Ĉi tio estas pri la homidoj, ke Dio ilin elprovu, kaj ke ili vidu, ke ili estas bruto per si mem."],[3,19,"Ĉar la sorto de homidoj kaj la sorto de bruto estas sorto egala: kiel ĉi tiuj mortas, tiel mortas ankaŭ tiuj, kaj sama spirito estas en ĉiuj; kaj supereco de homo kontraŭ bruto ne ekzistas, ĉar ĉio estas vantaĵo.","Ĉar la sorto de homidoj kaj la sorto de bruto estas sorto egala: kiel ĉi tiuj mortas, tiel mortas ankaŭ tiuj, kaj sama spirito estas en ĉiuj; kaj supereco de homo kontraŭ bruto ne ekzistas, ĉar ĉio estas vantaĵo."],[3,20,"Ĉiuj iras al unu loko: ĉiuj fariĝis el polvo, kaj ĉiuj refariĝos polvo.","Ĉiuj iras al unu loko: ĉiuj fariĝis el polvo, kaj ĉiuj refariĝos polvo."],[3,21,"Kiu scias, ĉu la spirito de homidoj leviĝas supren, kaj ĉu la spirito de bruto malleviĝas malsupren en la teron?","Kiu scias, ĉu la spirito de homidoj leviĝas supren, kaj ĉu la spirito de bruto malleviĝas malsupren en la teron?"],[3,22,"Kaj mi ekvidis, ke ekzistas nenio pli bona, ol ke homo ĝuu plezuron de siaj faroj, ĉar tia estas lia sorto; ĉar kiu alkondukos lin, por vidi, kio estas post li?","Kaj mi ekvidis, ke ekzistas nenio pli bona, ol ke homo ĝuu plezuron de siaj faroj, ĉar tia estas lia sorto; ĉar kiu alkondukos lin, por vidi, kio estas post li?"],[4,1,"Kaj mi returniĝis, kaj mi vidis ĉiujn premojn, kiuj estas farataj sub la suno: kaj jen estas larmoj de prematoj, kaj ne ekzistas por ili konsolanto; kaj perforteco de la mano de iliaj premantoj, kaj ne ekzistas por ili konsolanto.","Kaj mi returniĝis, kaj mi vidis ĉiujn premojn, kiuj estas farataj sub la suno: kaj jen estas larmoj de prematoj, kaj ne ekzistas por ili konsolanto; kaj perforteco de la mano de iliaj premantoj, kaj ne ekzistas por ili konsolanto."],[4,2,"Kaj mi trovis, ke la mortintoj, kiuj jam antaŭ longe mortis, estas pli feliĉaj ol la vivantoj, kiuj vivas ĝis nun;","Kaj mi trovis, ke la mortintoj, kiuj jam antaŭ longe mortis, estas pli feliĉaj ol la vivantoj, kiuj vivas ĝis nun;"],[4,3,"kaj pli feliĉa ol ili ambaŭ estas tiu, kiu ĝis nun ne ekzistis, kiu ne vidis la malbonajn farojn, kiuj estas farataj sub la suno.","kaj pli feliĉa ol ili ambaŭ estas tiu, kiu ĝis nun ne ekzistis, kiu ne vidis la malbonajn farojn, kiuj estas farataj sub la suno."],[4,4,"Mi vidis ankaŭ, ke ĉia laboro kaj ĉia lerteco en la faroj estas nur konkurado de unu kontraŭ alia; kaj ankaŭ ĉi tio estas vantaĵo kaj ventaĵo.","Mi vidis ankaŭ, ke ĉia laboro kaj ĉia lerteco en la faroj estas nur konkurado de unu kontraŭ alia; kaj ankaŭ ĉi tio estas vantaĵo kaj ventaĵo."],[4,5,"Malsaĝulo kunmetas siajn manojn, kaj formanĝas sian korpon.","Malsaĝulo kunmetas siajn manojn, kaj formanĝas sian korpon."],[4,6,"Pli bona estas plenmano da trankvilanimeco, ol ambaŭmano da penado kaj ventaĵo.","Pli bona estas plenmano da trankvilanimeco, ol ambaŭmano da penado kaj ventaĵo."],[4,7,"Kaj denove mi turniĝis, kaj vidis vantaĵon sub la suno:","Kaj denove mi turniĝis, kaj vidis vantaĵon sub la suno:"],[4,8,"jen estas solulo, kaj neniun alian li havas; nek filon nek fraton li havas; kaj tamen ne havas finon lia laborado, kaj lia okulo ne povas satiĝi de riĉeco; por kiu do mi laboras kaj senigas mian animon de ĝuado? Ĉi tio ankaŭ estas vantaĵo kaj malbona afero.","jen estas solulo, kaj neniun alian li havas; nek filon nek fraton li havas; kaj tamen ne havas finon lia laborado, kaj lia okulo ne povas satiĝi de riĉeco; por kiu do mi laboras kaj senigas mian animon de ĝuado? Ĉi tio ankaŭ estas vantaĵo kaj malbona afero."],[4,9,"Pli bone estas al du ol al unu, ĉar ili havas bonan rekompencon por sia laborado.","Pli bone estas al du ol al unu, ĉar ili havas bonan rekompencon por sia laborado."],[4,10,"Ĉar se ili falos, unu levos la alian; sed ve al solulo, se li falos, kaj se ne estas alia, kiu lin levus.","Ĉar se ili falos, unu levos la alian; sed ve al solulo, se li falos, kaj se ne estas alia, kiu lin levus."],[4,11,"Ankaŭ se du kuŝiĝas, estas al ili varme; sed unu — kiel li varmiĝos?","Ankaŭ se du kuŝiĝas, estas al ili varme; sed unu — kiel li varmiĝos?"],[4,12,"Kaj se iu montros sin pli forta kontraŭ unu, tiam ambaŭ kontraŭstaros lin; eĉ fadeno triopigita ne baldaŭ disŝiriĝos.","Kaj se iu montros sin pli forta kontraŭ unu, tiam ambaŭ kontraŭstaros lin; eĉ fadeno triopigita ne baldaŭ disŝiriĝos."],[4,13,"Pli bona estas knabo malriĉa sed saĝa, ol reĝo maljuna sed malsaĝa, kiu jam ne povas akiri scion.","Pli bona estas knabo malriĉa sed saĝa, ol reĝo maljuna sed malsaĝa, kiu jam ne povas akiri scion."],[4,14,"Iu el malliberejo eliris, kaj fariĝis reĝo; alia por reĝeco naskiĝis, kaj tamen estas malriĉa.","Iu el malliberejo eliris, kaj fariĝis reĝo; alia por reĝeco naskiĝis, kaj tamen estas malriĉa."],[4,15,"Mi vidis, ke ĉiu vivanto iras sub la suno kun la junulo: ĝi estas la alia, kiu okupos lian lokon.","Mi vidis, ke ĉiu vivanto iras sub la suno kun la junulo: ĝi estas la alia, kiu okupos lian lokon."],[4,16,"Senfina estas la popolo, antaŭ kiu li estis, kaj tamen la posteuloj ne ĝojos pri li; ankaŭ ĉi tio estas vantaĵo kaj ventaĵo.","Senfina estas la popolo, antaŭ kiu li estis, kaj tamen la posteuloj ne ĝojos pri li; ankaŭ ĉi tio estas vantaĵo kaj ventaĵo."],[5,1,"Gardu vian piedon, kiam vi iros en la domon de Dio, kaj estu preta pli por aŭskultado, ol por oferdonado de malsaĝuloj; ĉar ili ne scias, ke ili agas malbone.","Gardu vian piedon, kiam vi iros en la domon de Dio, kaj estu preta pli por aŭskultado, ol por oferdonado de malsaĝuloj; ĉar ili ne scias, ke ili agas malbone."],[5,2,"Ne rapidu kun via buŝo, kaj via koro ne rapidu elparoli vorton antaŭ Dio, ĉar Dio estas en la ĉielo, kaj vi estas sur la tero; tial malmultaj estu viaj vortoj.","Ne rapidu kun via buŝo, kaj via koro ne rapidu elparoli vorton antaŭ Dio, ĉar Dio estas en la ĉielo, kaj vi estas sur la tero; tial malmultaj estu viaj vortoj."],[5,3,"Ĉar sonĝo prezentiĝas per multe da agado, kaj parolo de malsaĝulo konsistas el multe da vortoj.","Ĉar sonĝo prezentiĝas per multe da agado, kaj parolo de malsaĝulo konsistas el multe da vortoj."],[5,4,"Kiam vi faros promeson al Dio, ne prokrastu ĝin plenumi; ĉar malagrablaj al Li estas malsaĝuloj: kion vi promesis, tion plenumu.","Kiam vi faros promeson al Dio, ne prokrastu ĝin plenumi; ĉar malagrablaj al Li estas malsaĝuloj: kion vi promesis, tion plenumu."],[5,5,"Pli bone estas, ke vi ne faru promeson, ol fari promeson kaj ne plenumi.","Pli bone estas, ke vi ne faru promeson, ol fari promeson kaj ne plenumi."],[5,6,"Ne permesu al via buŝo pekigi vian korpon, kaj ne diru al la sendito de Dio, ke ĝi estas eraro; kial fari, ke Dio koleru pro via parolo, kaj ke Li detruu la faron de viaj manoj?","Ne permesu al via buŝo pekigi vian korpon, kaj ne diru al la sendito de Dio, ke ĝi estas eraro; kial fari, ke Dio koleru pro via parolo, kaj ke Li detruu la faron de viaj manoj?"],[5,7,"Ĉe multo da sonĝoj kaj vantaĵoj estas ankaŭ multe da vortoj; sed vi timu Dion.","Ĉe multo da sonĝoj kaj vantaĵoj estas ankaŭ multe da vortoj; sed vi timu Dion."],[5,8,"Se premadon de malriĉulo kaj rompadon de justeco kaj honesteco vi vidas en lando, ne miru; ĉar pli alta kontrolas pli altan, kaj plej altaj ilin kontrolas.","Se premadon de malriĉulo kaj rompadon de justeco kaj honesteco vi vidas en lando, ne miru; ĉar pli alta kontrolas pli altan, kaj plej altaj ilin kontrolas."],[5,9,"Kaj superecon en ĉio havas tiu lando, en kiu la reĝo servas al la tero.","Kaj superecon en ĉio havas tiu lando, en kiu la reĝo servas al la tero."],[5,10,"Kiu amas monon, tiu ne satiĝos per mono; kaj kiu amas riĉecon, al tiu ĝi ne donos utilon: ankaŭ ĉi tio estas vantaĵo.","Kiu amas monon, tiu ne satiĝos per mono; kaj kiu amas riĉecon, al tiu ĝi ne donos utilon: ankaŭ ĉi tio estas vantaĵo."],[5,11,"Ju pli estas da havo, des pli multaj estas ĝiaj konsumantoj; kaj kian profiton havas ĝia mastro, krom vidi ĝin per siaj okuloj?","Ju pli estas da havo, des pli multaj estas ĝiaj konsumantoj; kaj kian profiton havas ĝia mastro, krom vidi ĝin per siaj okuloj?"],[5,12,"Dolĉa estas la dormo de laboranto, ĉu li manĝas malmulte aŭ multe; sed trosateco ne lasas la riĉulon dormi.","Dolĉa estas la dormo de laboranto, ĉu li manĝas malmulte aŭ multe; sed trosateco ne lasas la riĉulon dormi."],[5,13,"Turmentan malbonon mi vidis sub la suno: riĉecon konservatan por la malutilo de ĝia propra mastro.","Turmentan malbonon mi vidis sub la suno: riĉecon konservatan por la malutilo de ĝia propra mastro."],[5,14,"Kaj pereas ĉi tiu riĉeco en malfavoraj cirkonstancoj; naskiĝas filo, kaj li nenion havas en la mano.","Kaj pereas ĉi tiu riĉeco en malfavoraj cirkonstancoj; naskiĝas filo, kaj li nenion havas en la mano."],[5,15,"Kiel li eliris el la ventro de sia patrino, tiel nuda li foriras, kiel li venis; kaj nenion li elportas el sia laboro, kion li povus porti en la mano.","Kiel li eliris el la ventro de sia patrino, tiel nuda li foriras, kiel li venis; kaj nenion li elportas el sia laboro, kion li povus porti en la mano."],[5,16,"Kaj ĉi tio estas turmenta doloro, ke kiel li venis, tiel li foriras; kian do profiton li havas de tio, ke li laboras por la vento?","Kaj ĉi tio estas turmenta doloro, ke kiel li venis, tiel li foriras; kian do profiton li havas de tio, ke li laboras por la vento?"],[5,17,"Kaj ĉiujn siajn tagojn li konsumis en mallumo, en multe da ekscitiĝo, en malsano kaj malagrablaĵoj!","Kaj ĉiujn siajn tagojn li konsumis en mallumo, en multe da ekscitiĝo, en malsano kaj malagrablaĵoj!"],[5,18,"Jen, kion mi vidis: ke estas bone kaj bele manĝi kaj trinki kaj ĝui plezurojn de ĉiuj siaj laboroj, kiujn homo laboras sub la suno dum la tagoj de sia vivo, kiujn donis al li Dio; ĉar tio estas lia apartenaĵo.","Jen, kion mi vidis: ke estas bone kaj bele manĝi kaj trinki kaj ĝui plezurojn de ĉiuj siaj laboroj, kiujn homo laboras sub la suno dum la tagoj de sia vivo, kiujn donis al li Dio; ĉar tio estas lia apartenaĵo."],[5,19,"Kaj se al iu homo Dio donis riĉecon kaj havon, kaj donis al li la povon konsumi ilin kaj preni sian parton kaj ĝui plezuron de siaj laboroj, ĉi tio estas dono de Dio.","Kaj se al iu homo Dio donis riĉecon kaj havon, kaj donis al li la povon konsumi ilin kaj preni sian parton kaj ĝui plezuron de siaj laboroj, ĉi tio estas dono de Dio."],[5,20,"Ĉar ne longe li memoros la tagojn de sia vivo; Dio donas al li ĝojon de lia koro.","Ĉar ne longe li memoros la tagojn de sia vivo; Dio donas al li ĝojon de lia koro."],[6,1,"Ekzistas malbono, kiun mi vidis sub la suno, kaj granda ĝi estas por la homo:","Ekzistas malbono, kiun mi vidis sub la suno, kaj granda ĝi estas por la homo:"],[6,2,"se al iu homo Dio donas riĉecon kaj havon kaj honoron, kaj al lia animo mankas nenio, kion ajn li dezirus, sed Dio ne donas al li la povon konsumi ĝin, nur fremda homo ĝin konsumas — ĉi tio estas vantaĵo kaj malfacila doloro.","se al iu homo Dio donas riĉecon kaj havon kaj honoron, kaj al lia animo mankas nenio, kion ajn li dezirus, sed Dio ne donas al li la povon konsumi ĝin, nur fremda homo ĝin konsumas — ĉi tio estas vantaĵo kaj malfacila doloro."],[6,3,"Se iu homo naskigus cent infanojn kaj vivus multajn jarojn kaj atingus profundan aĝon, sed lia animo ne ĝuus sate la havon, kaj eĉ bonan enterigon li ne havus — tiam mi dirus: Pli feliĉa ol li estas abortito.","Se iu homo naskigus cent infanojn kaj vivus multajn jarojn kaj atingus profundan aĝon, sed lia animo ne ĝuus sate la havon, kaj eĉ bonan enterigon li ne havus — tiam mi dirus: Pli feliĉa ol li estas abortito."],[6,4,"Ĉar ĉi tiu vante venis kaj en mallumon foriris, kaj en mallumo kaŝiĝos lia nomo.","Ĉar ĉi tiu vante venis kaj en mallumon foriris, kaj en mallumo kaŝiĝos lia nomo."],[6,5,"Eĉ la sunon li ne vidis kaj ne konis — al li estas pli trankvile ol al tiu.","Eĉ la sunon li ne vidis kaj ne konis — al li estas pli trankvile ol al tiu."],[6,6,"Kaj se tiu homo vivus du mil jarojn kaj la bonon ne ĝuus, ĉu ne al unu loko ĉiuj iros?","Kaj se tiu homo vivus du mil jarojn kaj la bonon ne ĝuus, ĉu ne al unu loko ĉiuj iros?"],[6,7,"Ĉiuj laboroj de homo estas por lia buŝo, kaj tamen lia animo ne estas satigebla.","Ĉiuj laboroj de homo estas por lia buŝo, kaj tamen lia animo ne estas satigebla."],[6,8,"Kaj kian superecon havas la saĝulo antaŭ malsaĝulo, la inteligenta malriĉulo antaŭ aliaj vivaj estaĵoj?","Kaj kian superecon havas la saĝulo antaŭ malsaĝulo, la inteligenta malriĉulo antaŭ aliaj vivaj estaĵoj?"],[6,9,"Pli bone estas vidi per la okuloj, ol imagi en la animo; ankaŭ ĉi tio estas vantaĵo kaj ventaĵo.","Pli bone estas vidi per la okuloj, ol imagi en la animo; ankaŭ ĉi tio estas vantaĵo kaj ventaĵo."],[6,10,"Kio ajn ekzistas, tio de longe havas nomon; kaj estas sciate, kia estas la homo, kaj ke li ne povas juĝe batali kun Tiu, kiu estas pli forta ol li.","Kio ajn ekzistas, tio de longe havas nomon; kaj estas sciate, kia estas la homo, kaj ke li ne povas juĝe batali kun Tiu, kiu estas pli forta ol li."],[6,11,"Ĉar ekzistas multe da aferoj, kiuj plimultigas la vantaĵon; kian do superecon havas la homo?","Ĉar ekzistas multe da aferoj, kiuj plimultigas la vantaĵon; kian do superecon havas la homo?"],[6,12,"Ĉar kiu scias, kio estas bona por la homo dum la tagoj de lia vanta vivo, kiun li pasigas kiel ombro? kaj kiu diros al la homo, kio estos post li sub la suno?","Ĉar kiu scias, kio estas bona por la homo dum la tagoj de lia vanta vivo, kiun li pasigas kiel ombro? kaj kiu diros al la homo, kio estos post li sub la suno?"],[7,1,"Pli bona estas bona nomo, ol bona oleo; kaj la tago de la morto estas pli bona, ol la tago de la naskiĝo.","Pli bona estas bona nomo, ol bona oleo; kaj la tago de la morto estas pli bona, ol la tago de la naskiĝo."],[7,2,"Pli bone estas iri en domon de funebro, ol iri en domon de festenado; ĉar morto estas la fino de ĉiu homo, kaj la vivanto notos ĉi tion en sia koro.","Pli bone estas iri en domon de funebro, ol iri en domon de festenado; ĉar morto estas la fino de ĉiu homo, kaj la vivanto notos ĉi tion en sia koro."],[7,3,"Pli bona estas plendo, ol rido; ĉar ĉe malĝojo de la vizaĝo pliboniĝas la koro.","Pli bona estas plendo, ol rido; ĉar ĉe malĝojo de la vizaĝo pliboniĝas la koro."],[7,4,"La koro de saĝuloj estas en domo de funebro, kaj la koro de malsaĝuloj en domo de ĝojo.","La koro de saĝuloj estas en domo de funebro, kaj la koro de malsaĝuloj en domo de ĝojo."],[7,5,"Pli bone estas aŭskulti riproĉon de saĝulo, ol aŭskulti kanton de malsaĝuloj.","Pli bone estas aŭskulti riproĉon de saĝulo, ol aŭskulti kanton de malsaĝuloj."],[7,6,"Ĉar simila al la kraketado de dornoj sub poto estas la ridado de la malsaĝuloj; kaj vantaĵo ĝi estas.","Ĉar simila al la kraketado de dornoj sub poto estas la ridado de la malsaĝuloj; kaj vantaĵo ĝi estas."],[7,7,"Ĉar perforteco forprenas la saĝon de saĝulo, kaj la prudenton malbonigas donaco.","Ĉar perforteco forprenas la saĝon de saĝulo, kaj la prudenton malbonigas donaco."],[7,8,"La fino de afero estas pli bona, ol ĝia komenco; pacienculo estas pli bona, ol malhumilulo.","La fino de afero estas pli bona, ol ĝia komenco; pacienculo estas pli bona, ol malhumilulo."],[7,9,"Ne rapidu koleri en via spirito; ĉar koleremeco loĝas en la brusto de malsaĝuloj.","Ne rapidu koleri en via spirito; ĉar koleremeco loĝas en la brusto de malsaĝuloj."],[7,10,"Ne diru: Kial la antaŭaj tagoj estis pli bonaj, ol la nunaj? ĉar ne el saĝeco vi ĉi tion demandus.","Ne diru: Kial la antaŭaj tagoj estis pli bonaj, ol la nunaj? ĉar ne el saĝeco vi ĉi tion demandus."],[7,11,"Bona estas saĝeco kune kun hereda havo, kaj ĝi estas profita al tiuj, kiuj vidas la sunon.","Bona estas saĝeco kune kun hereda havo, kaj ĝi estas profita al tiuj, kiuj vidas la sunon."],[7,12,"Ĉar la saĝeco estas ŝirmo tiel same, kiel mono estas ŝirmo; sed la supereco de scienco konsistas en tio, ke la saĝeco donas vivon al sia posedanto.","Ĉar la saĝeco estas ŝirmo tiel same, kiel mono estas ŝirmo; sed la supereco de scienco konsistas en tio, ke la saĝeco donas vivon al sia posedanto."],[7,13,"Rigardu la faron de Dio; ĉar kiu povas tion rektigi, kion Li kurbigis?","Rigardu la faron de Dio; ĉar kiu povas tion rektigi, kion Li kurbigis?"],[7,14,"En la tago de bonstato uzu la bonstaton, kaj en la tago de malfeliĉo atendu: ĉi tion kaj tion aranĝis Dio, por ke la homo nenion komprenu post Li.","En la tago de bonstato uzu la bonstaton, kaj en la tago de malfeliĉo atendu: ĉi tion kaj tion aranĝis Dio, por ke la homo nenion komprenu post Li."],[7,15,"Ĉion tion mi vidis en miaj vantaj tagoj: okazas, ke virtulo pereas ĉe sia virteco, kaj okazas, ke malvirtulo longe vivas ĉe sia malvirteco.","Ĉion tion mi vidis en miaj vantaj tagoj: okazas, ke virtulo pereas ĉe sia virteco, kaj okazas, ke malvirtulo longe vivas ĉe sia malvirteco."],[7,16,"Ne estu tro virta, kaj ne rezonu tro multe: kial vi devas vin konfuzi?","Ne estu tro virta, kaj ne rezonu tro multe: kial vi devas vin konfuzi?"],[7,17,"Ne malvirtu tro multe, kaj ne estu senprudenta: kial vi devas morti ne en via tempo?","Ne malvirtu tro multe, kaj ne estu senprudenta: kial vi devas morti ne en via tempo?"],[7,18,"Bone estas, se vi tenos vin je unu afero kaj ankaŭ de alia afero vi ne forprenos vian manon; ĉar tiu, kiu timas Dion, penas plaĉi al ĉiuj.","Bone estas, se vi tenos vin je unu afero kaj ankaŭ de alia afero vi ne forprenos vian manon; ĉar tiu, kiu timas Dion, penas plaĉi al ĉiuj."],[7,19,"La saĝeco faras la saĝulon pli forta, ol dek potenculoj en la urbo.","La saĝeco faras la saĝulon pli forta, ol dek potenculoj en la urbo."],[7,20,"Ĉar ne ekzistas sur la tero virtulo, kiu farus nur bonon kaj ne pekus.","Ĉar ne ekzistas sur la tero virtulo, kiu farus nur bonon kaj ne pekus."],[7,21,"Ne ĉiujn vortojn, kiujn oni diras, atentu en via koro, por ke vi ne aŭdu vian sklavon malbenanta vin:","Ne ĉiujn vortojn, kiujn oni diras, atentu en via koro, por ke vi ne aŭdu vian sklavon malbenanta vin:"],[7,22,"ĉar multajn fojojn konsciis via koro, ke ankaŭ vi malbenis aliajn.","ĉar multajn fojojn konsciis via koro, ke ankaŭ vi malbenis aliajn."],[7,23,"Ĉion ĉi tion mi provis per mia saĝo; mi diris al mi: Mi akiru saĝon; tamen ĝi estas malproksima de mi.","Ĉion ĉi tion mi provis per mia saĝo; mi diris al mi: Mi akiru saĝon; tamen ĝi estas malproksima de mi."],[7,24,"Kio estas malproksima kaj tre profunda, kiu tion komprenos?","Kio estas malproksima kaj tre profunda, kiu tion komprenos?"],[7,25,"Mi turnis min kun mia koro, por ekkoni, esplori, kaj traserĉi saĝecon kaj prudenton, kaj ekscii, ke la malvirteco estas malsaĝeco kaj ke la senscieco estas sensenca.","Mi turnis min kun mia koro, por ekkoni, esplori, kaj traserĉi saĝecon kaj prudenton, kaj ekscii, ke la malvirteco estas malsaĝeco kaj ke la senscieco estas sensenca."],[7,26,"Kaj mi trovas, ke pli malbona ol la morto estas la virino, kiu estas kaptilo, kaj kies koro estas reto, kaj kies manoj estas katenoj; tiu, kiu plaĉas al Dio, sin savos de ŝi, sed pekulo estos kaptita de ŝi.","Kaj mi trovas, ke pli malbona ol la morto estas la virino, kiu estas kaptilo, kaj kies koro estas reto, kaj kies manoj estas katenoj; tiu, kiu plaĉas al Dio, sin savos de ŝi, sed pekulo estos kaptita de ŝi."],[7,27,"Jen, kion mi trovis, diris la Predikanto: oni devas kunigi unu fakton kun alia, por veni al konkludo.","Jen, kion mi trovis, diris la Predikanto: oni devas kunigi unu fakton kun alia, por veni al konkludo."],[7,28,"Jen, kion ankoraŭ serĉis mia animo kaj ne trovis: viron unu inter mil mi trovis, sed virinon inter ĉiuj mi tute ne trovis.","Jen, kion ankoraŭ serĉis mia animo kaj ne trovis: viron unu inter mil mi trovis, sed virinon inter ĉiuj mi tute ne trovis."],[7,29,"Nur ĉi tion mi trovis, ke Dio kreis la homon virtema; sed la homoj fordonis sin al multaj artifikoj.","Nur ĉi tion mi trovis, ke Dio kreis la homon virtema; sed la homoj fordonis sin al multaj artifikoj."],[8,1,"Kiu estas simila al saĝulo? kaj kiu komprenas la sencon de la aferoj? Saĝeco de homo lumigas lian vizaĝon, kaj la maldelikateco de lia vizaĝo ŝanĝiĝas.","Kiu estas simila al saĝulo? kaj kiu komprenas la sencon de la aferoj? Saĝeco de homo lumigas lian vizaĝon, kaj la maldelikateco de lia vizaĝo ŝanĝiĝas."],[8,2,"Mi diras: La reĝan ordonon plenumu, pro la ĵuro farita antaŭ Dio.","Mi diras: La reĝan ordonon plenumu, pro la ĵuro farita antaŭ Dio."],[8,3,"Ne rapidu foriri de antaŭ li, kaj ne estu persistema en malbona afero; ĉar ĉion, kion li volos, li povos fari.","Ne rapidu foriri de antaŭ li, kaj ne estu persistema en malbona afero; ĉar ĉion, kion li volos, li povos fari."],[8,4,"Ĉar la vorto de reĝo estas potenca; kaj kiu povas diri al li: Kion vi faras?","Ĉar la vorto de reĝo estas potenca; kaj kiu povas diri al li: Kion vi faras?"],[8,5,"Kiu plenumas la ordonon, tiu spertos nenion malbonan; tempon kaj manieron de agado scias la koro de saĝulo.","Kiu plenumas la ordonon, tiu spertos nenion malbonan; tempon kaj manieron de agado scias la koro de saĝulo."],[8,6,"Ĉar por ĉiu afero estas ĝia tempo kaj ĝia maniero; kaj granda estas por la homo la malbono de tio,","Ĉar por ĉiu afero estas ĝia tempo kaj ĝia maniero; kaj granda estas por la homo la malbono de tio,"],[8,7,"ke li ne scias, kio estos; ĉar kiu diros al vi, kiel estos?","ke li ne scias, kio estos; ĉar kiu diros al vi, kiel estos?"],[8,8,"Neniu homo povas regi la venton kaj reteni la venton, neniu povas regi la tagon de la morto; ne ekzistas forpermeso en tiu milito, kaj malvirteco ne savas sian faranton.","Neniu homo povas regi la venton kaj reteni la venton, neniu povas regi la tagon de la morto; ne ekzistas forpermeso en tiu milito, kaj malvirteco ne savas sian faranton."],[8,9,"Ĉion ĉi tion mi vidis, kaj mi atentis ĉiun aferon, kiu estas farata sub la suno, kaj tiun tempon, en kiu homo regas homon al lia malbono.","Ĉion ĉi tion mi vidis, kaj mi atentis ĉiun aferon, kiu estas farata sub la suno, kaj tiun tempon, en kiu homo regas homon al lia malbono."],[8,10,"Kaj ankaŭ mi vidis, ke oni enterigis malvirtulojn, kiuj venadis kaj eliradis el la sankta loko, kaj kiuj estis forgesitaj en la urbo, kie ili tiel agis; kaj ĉi tio ankaŭ estas vantaĵo.","Kaj ankaŭ mi vidis, ke oni enterigis malvirtulojn, kiuj venadis kaj eliradis el la sankta loko, kaj kiuj estis forgesitaj en la urbo, kie ili tiel agis; kaj ĉi tio ankaŭ estas vantaĵo."],[8,11,"Ĉar ne baldaŭ estas farata juĝo kontraŭ malbonaj faroj, tial plene kuraĝas la koro de homidoj fari malbonon.","Ĉar ne baldaŭ estas farata juĝo kontraŭ malbonaj faroj, tial plene kuraĝas la koro de homidoj fari malbonon."],[8,12,"Kvankam pekulo faras malbonon cent fojojn, kaj Dio estas pacienca al li, tamen mi scias, ke estos bone al tiuj, kiuj timas Dion, kiuj respektas Lin.","Kvankam pekulo faras malbonon cent fojojn, kaj Dio estas pacienca al li, tamen mi scias, ke estos bone al tiuj, kiuj timas Dion, kiuj respektas Lin."],[8,13,"Kaj ne estos bone al malvirtulo, kaj ne tenos sin longe, simile al ombro, tiu, kiu ne timas Dion.","Kaj ne estos bone al malvirtulo, kaj ne tenos sin longe, simile al ombro, tiu, kiu ne timas Dion."],[8,14,"Ekzistas vantaĵo, kiu fariĝas sur la tero: ekzistas virtuloj, al kiuj fariĝas tio sama, kio fariĝas al malvirtuloj; kaj ekzistas malvirtuloj, al kiuj fariĝas tio sama, kio al la virtuloj; kaj mi diris al mi, ke ankaŭ ĉi tio estas vantaĵo.","Ekzistas vantaĵo, kiu fariĝas sur la tero: ekzistas virtuloj, al kiuj fariĝas tio sama, kio fariĝas al malvirtuloj; kaj ekzistas malvirtuloj, al kiuj fariĝas tio sama, kio al la virtuloj; kaj mi diris al mi, ke ankaŭ ĉi tio estas vantaĵo."],[8,15,"Kaj mi eklaŭdis la gajecon, ĉar ne ekzistas io pli bona por homo sub la suno, ol manĝi, trinki, kaj gaji, kaj ke ĉi tio akompanu lin en liaj laboroj en la tagoj de lia vivo, kiujn donis al li Dio sub la suno.","Kaj mi eklaŭdis la gajecon, ĉar ne ekzistas io pli bona por homo sub la suno, ol manĝi, trinki, kaj gaji, kaj ke ĉi tio akompanu lin en liaj laboroj en la tagoj de lia vivo, kiujn donis al li Dio sub la suno."],[8,16,"Kiam mi direktis mian koron, por ekkoni saĝecon, kaj por ĉirkaŭrigardi la aferojn, kiuj estas farataj sur la tero tiamaniere, ke nek tage nek nokte homo vidas dormon sur siaj okuloj; kaj kiam mi rigardis ĉiujn farojn de Dio:","Kiam mi direktis mian koron, por ekkoni saĝecon, kaj por ĉirkaŭrigardi la aferojn, kiuj estas farataj sur la tero tiamaniere, ke nek tage nek nokte homo vidas dormon sur siaj okuloj; kaj kiam mi rigardis ĉiujn farojn de Dio:"],[8,17,"tiam mi trovis, ke homo ne povas kompreni la aferojn, kiuj fariĝas sub la suno; kiom ajn la homo penus esplori, li ne komprenos; kaj se eĉ saĝulo diras, ke li scias, li tamen ne povas kompreni.","tiam mi trovis, ke homo ne povas kompreni la aferojn, kiuj fariĝas sub la suno; kiom ajn la homo penus esplori, li ne komprenos; kaj se eĉ saĝulo diras, ke li scias, li tamen ne povas kompreni."],[9,1,"Al ĉio ĉi tio mi direktis mian koron, por esplori ĉion ĉi tion, ke la virtuloj kaj saĝuloj kaj iliaj faroj estas en la mano de Dio; kaj nek amon nek malamon scias la homo, kaj nenion, kio lin atendas.","Al ĉio ĉi tio mi direktis mian koron, por esplori ĉion ĉi tion, ke la virtuloj kaj saĝuloj kaj iliaj faroj estas en la mano de Dio; kaj nek amon nek malamon scias la homo, kaj nenion, kio lin atendas."],[9,2,"Al ĉiuj estas la sama sorto: al la virtulo kaj al la malvirtulo, al la bona kaj pura kaj al la malpura, al la oferfaranto kaj al tiu, kiu ne oferfaras, al la bonulo kaj al la pekulo, al la ĵuranto kaj al tiu, kiu timas ĵuron.","Al ĉiuj estas la sama sorto: al la virtulo kaj al la malvirtulo, al la bona kaj pura kaj al la malpura, al la oferfaranto kaj al tiu, kiu ne oferfaras, al la bonulo kaj al la pekulo, al la ĵuranto kaj al tiu, kiu timas ĵuron."],[9,3,"Ĉi tio estas malbona en ĉio, kio fariĝas sub la suno, ke la sama sorto ekzistas por ĉiuj, kaj la koro de la homidoj estas plena de malbono, kaj sensencaĵo estas en ilia koro dum ilia vivado, kaj poste ili transiras al la mortintoj.","Ĉi tio estas malbona en ĉio, kio fariĝas sub la suno, ke la sama sorto ekzistas por ĉiuj, kaj la koro de la homidoj estas plena de malbono, kaj sensencaĵo estas en ilia koro dum ilia vivado, kaj poste ili transiras al la mortintoj."],[9,4,"Ĉar kiu troviĝas inter la vivuloj, tiu havas ankoraŭ esperon; ĉar eĉ al hundo vivanta estas pli bone, ol al leono mortinta.","Ĉar kiu troviĝas inter la vivuloj, tiu havas ankoraŭ esperon; ĉar eĉ al hundo vivanta estas pli bone, ol al leono mortinta."],[9,5,"Ĉar la vivantoj scias, ke ili mortos; kaj la mortintoj scias nenion, kaj por ili jam ne ekzistas rekompenco, ĉar la memoro pri ili estas forgesita.","Ĉar la vivantoj scias, ke ili mortos; kaj la mortintoj scias nenion, kaj por ili jam ne ekzistas rekompenco, ĉar la memoro pri ili estas forgesita."],[9,6,"Kaj ilia amo, kaj ilia malamo, kaj ilia ĵaluzo jam de longe malaperis; kaj jam por neniam ili havas partoprenon en io, kio fariĝas sub la suno.","Kaj ilia amo, kaj ilia malamo, kaj ilia ĵaluzo jam de longe malaperis; kaj jam por neniam ili havas partoprenon en io, kio fariĝas sub la suno."],[9,7,"Iru, manĝu ĝoje vian panon, kaj trinku kun gaja koro vian vinon, se Dio favoris viajn aferojn.","Iru, manĝu ĝoje vian panon, kaj trinku kun gaja koro vian vinon, se Dio favoris viajn aferojn."],[9,8,"En ĉiu tempo viaj vestoj estu blankaj, kaj oleo ne manku sur via kapo.","En ĉiu tempo viaj vestoj estu blankaj, kaj oleo ne manku sur via kapo."],[9,9,"Ĝuu la vivon kun la edzino, kiun vi amas en la tempo de via tuta vanta vivo, kaj kiun Dio donis al vi por ĉiuj viaj vantaj tagoj; ĉar ĉi tio estas via apartenaĵo en via vivo, kaj en viaj laboroj, kiujn vi laboris sub la suno.","Ĝuu la vivon kun la edzino, kiun vi amas en la tempo de via tuta vanta vivo, kaj kiun Dio donis al vi por ĉiuj viaj vantaj tagoj; ĉar ĉi tio estas via apartenaĵo en via vivo, kaj en viaj laboroj, kiujn vi laboris sub la suno."],[9,10,"Kion ajn via mano povas fari laŭ via forto, tion faru; ĉar ekzistas nek faro, nek kalkulo, nek scio, nek saĝo, en Ŝeol, kien vi iros.","Kion ajn via mano povas fari laŭ via forto, tion faru; ĉar ekzistas nek faro, nek kalkulo, nek scio, nek saĝo, en Ŝeol, kien vi iros."],[9,11,"Aliflanke mi vidis sub la suno, ke ne de la rapiduloj dependas la kuro, ne de la fortuloj dependas la milito, kaj ne la saĝuloj havas panon, kaj ne la talentuloj havas riĉecon, kaj ne la kompetentuloj trovas aprobon; nur de la tempo kaj okazo ili ĉiuj dependas.","Aliflanke mi vidis sub la suno, ke ne de la rapiduloj dependas la kuro, ne de la fortuloj dependas la milito, kaj ne la saĝuloj havas panon, kaj ne la talentuloj havas riĉecon, kaj ne la kompetentuloj trovas aprobon; nur de la tempo kaj okazo ili ĉiuj dependas."],[9,12,"Ĉar eĉ ne scias la homo sian sorton; kiel fiŝoj, kaptitaj en pereigan reton, kaj kiel birdoj, implikiĝintaj en kaptilon, tiel kaptiĝas la homoj en tempo malbona, kiam ĝi atakas ilin neatendite.","Ĉar eĉ ne scias la homo sian sorton; kiel fiŝoj, kaptitaj en pereigan reton, kaj kiel birdoj, implikiĝintaj en kaptilon, tiel kaptiĝas la homoj en tempo malbona, kiam ĝi atakas ilin neatendite."],[9,13,"Ankaŭ jenan saĝaĵon mi vidis sub la suno, kaj ĝi ŝajnis al mi granda:","Ankaŭ jenan saĝaĵon mi vidis sub la suno, kaj ĝi ŝajnis al mi granda:"],[9,14,"estis urbo malgranda, kaj malmulte da homoj ĝi havis; venis al ĝi granda reĝo, kaj sieĝis ĝin, kaj konstruis ĉirkaŭ ĝi grandajn sieĝajn fortikaĵojn;","estis urbo malgranda, kaj malmulte da homoj ĝi havis; venis al ĝi granda reĝo, kaj sieĝis ĝin, kaj konstruis ĉirkaŭ ĝi grandajn sieĝajn fortikaĵojn;"],[9,15,"sed troviĝis en ĝi homo malriĉa sed saĝa, kaj li savis la urbon per sia saĝeco; tamen neniu rememoris tiun malriĉan homon.","sed troviĝis en ĝi homo malriĉa sed saĝa, kaj li savis la urbon per sia saĝeco; tamen neniu rememoris tiun malriĉan homon."],[9,16,"Kaj mi diris: Pli bona estas saĝo ol forto, tamen la saĝo de malriĉulo estas malrespektata, kaj liaj vortoj ne estas aŭdataj.","Kaj mi diris: Pli bona estas saĝo ol forto, tamen la saĝo de malriĉulo estas malrespektata, kaj liaj vortoj ne estas aŭdataj."],[9,17,"La vortoj de saĝuloj, trankvile aŭskultitaj, estas pli bonaj ol la kriado de reganto inter malsaĝuloj.","La vortoj de saĝuloj, trankvile aŭskultitaj, estas pli bonaj ol la kriado de reganto inter malsaĝuloj."],[9,18,"Pli bona estas saĝo, ol militaj instrumentoj; kaj unu pekulo pereigas multe da bono.","Pli bona estas saĝo, ol militaj instrumentoj; kaj unu pekulo pereigas multe da bono."],[10,1,"Venenaj muŝoj putrigas kaj haladzigas la oleon de parfumisto; pli ŝatata ol saĝo kaj honoro ofte estas malgranda malsaĝaĵo.","Venenaj muŝoj putrigas kaj haladzigas la oleon de parfumisto; pli ŝatata ol saĝo kaj honoro ofte estas malgranda malsaĝaĵo."],[10,2,"La koro de saĝulo estas ĉe lia dekstra flanko, kaj la koro de malsaĝulo ĉe lia maldekstra.","La koro de saĝulo estas ĉe lia dekstra flanko, kaj la koro de malsaĝulo ĉe lia maldekstra."],[10,3,"Kaj eĉ en la vojo, laŭ kiu iras malsaĝulo, mankas al li saĝo, kaj al ĉiu li diras, ke li estas malsaĝulo.","Kaj eĉ en la vojo, laŭ kiu iras malsaĝulo, mankas al li saĝo, kaj al ĉiu li diras, ke li estas malsaĝulo."],[10,4,"Se atakos vin kolero de reganto, ne forlasu vian lokon, ĉar mildeco pardonigas eĉ grandajn krimojn.","Se atakos vin kolero de reganto, ne forlasu vian lokon, ĉar mildeco pardonigas eĉ grandajn krimojn."],[10,5,"Ekzistas malbono, kiun mi vidis sub la suno; ĝi estas kvazaŭ eraro, venanta de la reganto:","Ekzistas malbono, kiun mi vidis sub la suno; ĝi estas kvazaŭ eraro, venanta de la reganto:"],[10,6,"senscieco estas metata tre alte, kaj la riĉuloj sidas malalte.","senscieco estas metata tre alte, kaj la riĉuloj sidas malalte."],[10,7,"Mi vidis sklavojn sur ĉevaloj, kaj princojn, irantajn piede, kiel sklavoj.","Mi vidis sklavojn sur ĉevaloj, kaj princojn, irantajn piede, kiel sklavoj."],[10,8,"Kiu fosas kavon, tiu falos en ĝin; kaj kiu detruas muron, tiun mordos serpento.","Kiu fosas kavon, tiu falos en ĝin; kaj kiu detruas muron, tiun mordos serpento."],[10,9,"Kiu transmovas ŝtonojn, tiu faras al si difekton per streĉo; kaj kiu hakas lignon, tiu sin vundas per ĝi.","Kiu transmovas ŝtonojn, tiu faras al si difekton per streĉo; kaj kiu hakas lignon, tiu sin vundas per ĝi."],[10,10,"Se malakriĝis la hakilo, kaj oni ne akrigas la tranĉan flankon, oni devas streĉi la fortojn; kaj la ĉefaĵo estas prepari ĉion saĝe.","Se malakriĝis la hakilo, kaj oni ne akrigas la tranĉan flankon, oni devas streĉi la fortojn; kaj la ĉefaĵo estas prepari ĉion saĝe."],[10,11,"Se mordis la serpento sen kuracparolo, tiam jam ne utilas kuracparolanto.","Se mordis la serpento sen kuracparolo, tiam jam ne utilas kuracparolanto."],[10,12,"Vortoj el buŝo de saĝulo estas agrablaj, sed la buŝo de malsaĝulo lin mem pereigas.","Vortoj el buŝo de saĝulo estas agrablaj, sed la buŝo de malsaĝulo lin mem pereigas."],[10,13,"La komenco de la parolo de lia buŝo estas malsaĝaĵo, kaj la fino de lia parolo estas abomeninda sensencaĵo.","La komenco de la parolo de lia buŝo estas malsaĝaĵo, kaj la fino de lia parolo estas abomeninda sensencaĵo."],[10,14,"Malsaĝulo multe parolas, kvankam homo ne scias, kio estos; kaj kio estos post li? kiu ĉi tion diros al li?","Malsaĝulo multe parolas, kvankam homo ne scias, kio estos; kaj kio estos post li? kiu ĉi tion diros al li?"],[10,15,"Penado de malsaĝuloj lacigas ĉiun, kiu ne scias eĉ la vojon al la urbo.","Penado de malsaĝuloj lacigas ĉiun, kiu ne scias eĉ la vojon al la urbo."],[10,16,"Ve al vi, ho lando, se via reĝo estas infano kaj viaj princoj manĝas frue!","Ve al vi, ho lando, se via reĝo estas infano kaj viaj princoj manĝas frue!"],[10,17,"Feliĉa vi estas, ho lando, se via reĝo estas de nobla deveno kaj viaj princoj manĝas en ĝusta tempo, por fortiĝi, ne por festeni!","Feliĉa vi estas, ho lando, se via reĝo estas de nobla deveno kaj viaj princoj manĝas en ĝusta tempo, por fortiĝi, ne por festeni!"],[10,18,"De mallaboremeco falos la plafono; kaj, se oni mallevas la manojn, tramalsekiĝas la domo.","De mallaboremeco falos la plafono; kaj, se oni mallevas la manojn, tramalsekiĝas la domo."],[10,19,"Por plezuro oni aranĝas festenojn, kaj vino gajigas la vivon, kaj mono respondas por ĉio.","Por plezuro oni aranĝas festenojn, kaj vino gajigas la vivon, kaj mono respondas por ĉio."],[10,20,"Eĉ en viaj pensoj ne malbenu la reĝon, kaj en via dormoĉambro ne malbenu riĉulon; ĉar birdo ĉiela transportos vian voĉon, kaj flugila estaĵo eldiros vian parolon.","Eĉ en viaj pensoj ne malbenu la reĝon, kaj en via dormoĉambro ne malbenu riĉulon; ĉar birdo ĉiela transportos vian voĉon, kaj flugila estaĵo eldiros vian parolon."],[11,1,"Elsendu vian panon sur la akvon; ĉar post longa tempo vi ĝin retrovos.","Elsendu vian panon sur la akvon; ĉar post longa tempo vi ĝin retrovos."],[11,2,"Donu parton al sep, kaj eĉ al ok, ĉar vi ne scias, ĉu ne estos malfeliĉo sur la tero.","Donu parton al sep, kaj eĉ al ok, ĉar vi ne scias, ĉu ne estos malfeliĉo sur la tero."],[11,3,"Kiam la nuboj pleniĝos, ili verŝos pluvon sur la teron, kaj se falos arbo suden aŭ norden, ĝi tie restos, kien ĝi falis.","Kiam la nuboj pleniĝos, ili verŝos pluvon sur la teron, kaj se falos arbo suden aŭ norden, ĝi tie restos, kien ĝi falis."],[11,4,"Kiu observas la venton, tiu ne semos; kaj kiu rigardas la nubojn, tiu ne rikoltos.","Kiu observas la venton, tiu ne semos; kaj kiu rigardas la nubojn, tiu ne rikoltos."],[11,5,"Kiel vi ne scias, kian vojon iros la vento, kaj kiel formiĝas la ostoj en la ventro de gravedulino, tiel vi ne povas scii la faron de Dio, kiu ĉion faras.","Kiel vi ne scias, kian vojon iros la vento, kaj kiel formiĝas la ostoj en la ventro de gravedulino, tiel vi ne povas scii la faron de Dio, kiu ĉion faras."],[11,6,"Matene semu vian semon, kaj vespere via mano ne ripozu; ĉar vi ne scias, ĉu tio aŭ alio estos pli ĝusta, aŭ ĉu ambaŭ egale estos bonaj.","Matene semu vian semon, kaj vespere via mano ne ripozu; ĉar vi ne scias, ĉu tio aŭ alio estos pli ĝusta, aŭ ĉu ambaŭ egale estos bonaj."],[11,7,"Agrabla estas la lumo, kaj bone estas al la okuloj vidi la sunon.","Agrabla estas la lumo, kaj bone estas al la okuloj vidi la sunon."],[11,8,"Ĉar se eĉ multajn jarojn homo vivus, li ĝoju en ili ĉiuj; kaj li memoru pri la tagoj mallumaj, ĉar estos multe da ili; ĉio, kio venos, estas vantaĵo.","Ĉar se eĉ multajn jarojn homo vivus, li ĝoju en ili ĉiuj; kaj li memoru pri la tagoj mallumaj, ĉar estos multe da ili; ĉio, kio venos, estas vantaĵo."],[11,9,"Ĝoju, junulo, en via infaneco; kaj via koro ĝuu plezuron en la tagoj de via juneco, kaj iru, kien kondukas vin via koro kaj kien rigardas viaj okuloj; sed sciu, ke pri ĉio ĉi tio Dio venigos vin al juĝo.","Ĝoju, junulo, en via infaneco; kaj via koro ĝuu plezuron en la tagoj de via juneco, kaj iru, kien kondukas vin via koro kaj kien rigardas viaj okuloj; sed sciu, ke pri ĉio ĉi tio Dio venigos vin al juĝo."],[11,10,"Tial forpelu malĝojon de via koro, kaj forigu malagrablaĵon de via korpo; ĉar la infaneco kaj la juneco estas vantaĵo.","Tial forpelu malĝojon de via koro, kaj forigu malagrablaĵon de via korpo; ĉar la infaneco kaj la juneco estas vantaĵo."],[12,1,"Kaj memoru vian Kreinton en la tagoj de via juneco, dum ankoraŭ ne venis la tagoj de malbono, kaj ne venis la jaroj, pri kiuj vi diros: Mi ne havas plezuron de ili;","Kaj memoru vian Kreinton en la tagoj de via juneco, dum ankoraŭ ne venis la tagoj de malbono, kaj ne venis la jaroj, pri kiuj vi diros: Mi ne havas plezuron de ili;"],[12,2,"dum ne mallumiĝis la suno, la lumo, la luno, kaj la steloj, kaj ne revenis nuboj post la pluvo;","dum ne mallumiĝis la suno, la lumo, la luno, kaj la steloj, kaj ne revenis nuboj post la pluvo;"],[12,3,"en la tago, kiam ektremos la gardantoj de la domo, kaj malfortiĝos la militantoj, kaj ĉesos mueli la muelantinoj, ĉar estos malmulte da ili, kaj senvidiĝos la rigardantinoj tra la fenestroj;","en la tago, kiam ektremos la gardantoj de la domo, kaj malfortiĝos la militantoj, kaj ĉesos mueli la muelantinoj, ĉar estos malmulte da ili, kaj senvidiĝos la rigardantinoj tra la fenestroj;"],[12,4,"kaj fermitaj estos la pordoj al la strato, kiam eksilentos la sonado de la muelŝtono; kaj homo leviĝados laŭ la krio de birdo, kaj mallaŭtiĝos la sonoj de kantoj;","kaj fermitaj estos la pordoj al la strato, kiam eksilentos la sonado de la muelŝtono; kaj homo leviĝados laŭ la krio de birdo, kaj mallaŭtiĝos la sonoj de kantoj;"],[12,5,"kaj altaĵojn ili ektimos, kaj sur la vojo aperos teruroj, kaj ekfloros la migdalarbo, kaj peziĝos la lokusto, kaj malaperos deziro: tiam homo foriros en sian eternan domon, kaj sur la strato marŝos plorantoj;","kaj altaĵojn ili ektimos, kaj sur la vojo aperos teruroj, kaj ekfloros la migdalarbo, kaj peziĝos la lokusto, kaj malaperos deziro: tiam homo foriros en sian eternan domon, kaj sur la strato marŝos plorantoj;"],[12,6,"ĝis disŝiriĝos la arĝenta ĉeneto, rompiĝos la ora lampeto, rompiĝos la kruĉo ĉe la fonto, kaj falos la rado en la puton;","ĝis disŝiriĝos la arĝenta ĉeneto, rompiĝos la ora lampeto, rompiĝos la kruĉo ĉe la fonto, kaj falos la rado en la puton;"],[12,7,"kaj la polvo refariĝos tero, kiel ĝi estis, kaj la spirito reiros al Dio, kiu ĝin donis.","kaj la polvo refariĝos tero, kiel ĝi estis, kaj la spirito reiros al Dio, kiu ĝin donis."],[12,8,"Vantaĵo de vantaĵoj, diris la Predikanto; ĉio estas vantaĵo.","Vantaĵo de vantaĵoj, diris la Predikanto; ĉio estas vantaĵo."],[12,9,"Krom tio, ke la Predikanto estis saĝulo, li ankoraŭ instruis scion al la popolo; li ĉion pesis, esploris, kaj verkis multe da sentencoj.","Krom tio, ke la Predikanto estis saĝulo, li ankoraŭ instruis scion al la popolo; li ĉion pesis, esploris, kaj verkis multe da sentencoj."],[12,10,"Penis la Predikanto trovi agrablajn parolojn, kaj li skribis ĝuste vortojn de vero.","Penis la Predikanto trovi agrablajn parolojn, kaj li skribis ĝuste vortojn de vero."],[12,11,"La paroloj de saĝuloj estas kiel akraj pintoj, kaj kiel enbatitaj najloj estas la vortoj de publikaj parolistoj; ili estas donitaj de unu paŝtisto.","La paroloj de saĝuloj estas kiel akraj pintoj, kaj kiel enbatitaj najloj estas la vortoj de publikaj parolistoj; ili estas donitaj de unu paŝtisto."],[12,12,"Kaj krom tio, mia filo, akceptu mian instruon, ke se oni volus verki multajn librojn, ne estus fino, kaj multe legi lacigas la korpon.","Kaj krom tio, mia filo, akceptu mian instruon, ke se oni volus verki multajn librojn, ne estus fino, kaj multe legi lacigas la korpon."],[12,13,"Ni aŭskultu la finon de ĉio: timu Dion, kaj plenumu Liajn ordonojn, ĉar ĉi tio estas ĉio por la homo.","Ni aŭskultu la finon de ĉio: timu Dion, kaj plenumu Liajn ordonojn, ĉar ĉi tio estas ĉio por la homo."],[12,14,"Ĉar ĉiun faron Dio venigos al juĝo, eĉ ĉion kaŝitan, ĉu ĝi estas bona aŭ malbona.","Ĉar ĉiun faron Dio venigos al juĝo, eĉ ĉion kaŝitan, ĉu ĝi estas bona aŭ malbona."]]}};